/* Administrator workspace and doctor earnings; all figures come from the API. */
(()=>{
 'use strict';if(!window.RADAZ_PRODUCTION)return;
 const E=R.esc,P=R.platform,A={cache:new Map(),from:'',to:'',doctor:''};
 const owner=()=>R.state.user?.is_owner||R.state.user?.role==='admin';
 const tr=(az,ru,en)=>({az,ru,en}[R.lang]||az);
 const labels=()=>({overview:tr('Admin paneli','Панель администратора','Admin dashboard'),rules:tr('Qazanc ayarları','Настройки заработка','Earning settings'),report:tr('Həkim hesabatı','Отчёт по врачам','Doctor earnings report'),payments:tr('Ödəniş ayarları','Настройки оплаты','Payment settings'),viewer:tr('RADAZ bağlantısı','Подключение RADAZ','RADAZ connection'),contact:tr('Əlaqə ayarları','Контакты','Contact settings'),mine:tr('Qazancım','Мой заработок','My earnings')});
 const money=n=>(Number(n||0)/100).toLocaleString(R.lang==='az'?'az-AZ':R.lang,{minimumFractionDigits:2,maximumFractionDigits:2})+' ₼';
 const date=v=>new Date(v).toLocaleString(R.lang==='az'?'az-AZ':R.lang,{timeZone:'Asia/Baku',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
 const button=(label,action,extra='')=>`<button type="button" class="btn btn-outline btn-sm" data-action="${action}" ${extra}>${E(label)}</button>`;
 const heading=(title,sub='')=>`<div class="dashboard-heading"><div><span class="eyebrow">RADAZ · ${owner()?'ADMIN':tr('Şəxsi kabinet','Личный кабинет','My account')}</span><h1>${E(title)}</h1>${sub?`<p>${E(sub)}</p>`:''}</div>${button(tr('Yenilə','Обновить','Refresh'),'financeRefresh')}</div>`;
 const ruleText=r=>!r||r.mode==='unconfigured'?tr('Təyin edilməyib','Не задано','Not configured'):r.mode==='percentage'?`${r.value}%`:money(r.value*100)+tr(' / rapor',' / заключение',' / report');
 const basis=()=>tr('Yalnız real ödənişi təsdiqlənmiş, tamamlanmış raporlar hesablanır. Tarix raporun təsdiq tarixidir (Bakı vaxtı). Ödəniş sınaqları qazanca daxil deyil.','Учитываются только завершённые заключения с подтверждённой реальной оплатой. Дата — подтверждение заключения по времени Баку. Тестовые оплаты не учитываются.','Only completed reports with confirmed real payments count. Dates use report approval time in Baku. Test payments are excluded.');
 const table=(heads,body,empty)=>`<div class="a-table-scroll"><table class="a-table"><thead><tr>${heads.map(h=>`<th>${E(h)}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${heads.length}" class="a-empty">${E(empty||tr('Hələ məlumat yoxdur.','Пока нет данных.','No records yet.'))}</td></tr>`}</tbody></table></div>`;
 function resource(path){const key=R.state.user?.id+path;let item=A.cache.get(key);if(!item){item={loading:true};A.cache.set(key,item);R.request(path).then(data=>{item.data=data;item.loading=false;if(A.cache.get(key)===item)R.render();}).catch(e=>{item.error=e.message;item.loading=false;if(A.cache.get(key)===item)R.render();});}return item;}
 const pending=item=>item.error?`<section class="card" role="alert"><p>${E(item.error)}</p>${button(tr('Yenidən sına','Повторить','Retry'),'financeRefresh')}</section>`:`<section class="card" role="status">${tr('Məlumatlar yüklənir…','Загрузка данных…','Loading data…')}</section>`;
 function shell(title,html){const l=labels(),route=R.state.route,links=owner()?[['overview','grid'],['rules','settings'],['report','file'],['payments','lock'],['viewer','scan'],['contact','phone']]:[];const paths={overview:'overview',rules:'earnings-settings',report:'earnings',payments:'payments',viewer:'viewer',contact:'contact'};
  return `<div class="dashboard-shell a-shell"><aside class="dashboard-sidebar">${R.logo()}<span class="sidebar-caption">${owner()?'RADAZ ADMIN':'RADAZ'}</span><nav>${links.map(([k,icon])=>`<a href="#/admin/${paths[k]}" class="${route==='/admin/'+paths[k]||route==='/dashboard'&&k==='overview'?'active':''}">${R.icon(icon,18)} ${E(l[k])}</a>`).join('')}${!owner()?`<a class="active" href="#/earnings">${R.icon('file',18)} ${E(l.mine)}</a>`:''}<a href="#/dashboard" ${owner()?'data-action="openDoctorCabinet"':''}>${R.icon('scan',18)} ${tr('Həkim kabineti','Кабинет врача','Doctor workspace')}</a><a href="#/templates">${R.icon('file',18)} ${R.t('Şablon kitabxanası')}</a><a href="#/">${R.icon('external',18)} ${R.t('Sayta qayıt')}</a></nav><div class="sidebar-bottom"><div class="sidebar-account"><span><strong>${E(R.state.user?.name||'RADAZ')}</strong><small>${owner()?tr('Administrator','Администратор','Administrator'):tr('Radioloq','Радиолог','Radiologist')}</small></span><button class="icon-btn" data-action="logout" aria-label="${R.t('Çıxış')}">${R.icon('logout',18)}</button></div></div></aside><div class="dashboard-main"><header class="dashboard-top"><strong>${E(title)}</strong>${R.languagePicker()}</header><main class="dashboard-content a-content">${html}</main></div></div>`;
 }
 const cards=(items)=>`<div class="a-stats">${items.map(([title,value,note])=>`<section class="card a-stat"><span>${E(title)}</span><strong>${E(value)}</strong>${note?`<small>${E(note)}</small>`:''}</section>`).join('')}</div>`;
 function overview(){const l=labels(),item=resource('/admin/overview');if(!item.data)return shell(l.overview,heading(l.overview)+pending(item));const d=item.data,count=(role,approved)=>d.users.filter(u=>u.role===role&&(approved===undefined||!!u.approved===approved)).reduce((n,u)=>n+u.count,0);
  return shell(l.overview,heading(l.overview,tr('Saytın idarə edilməsi, həkimlər və qazanc hesabatları','Управление сайтом, врачами и заработком','Manage the site, doctors and earnings'))+cards([[tr('Qeydiyyatlı pasiyentlər','Пациенты','Registered patients'),count('patient')],[tr('Təsdiqlənmiş həkimlər','Подтверждённые врачи','Approved doctors'),count('doctor',true)],[tr('Gözləyən raporlar','Ожидающие заключения','Pending reports'),d.cases.waiting],[tr('Bu ay həkim qazancı','Заработок врачей за месяц','Doctor earnings this month'),money(d.monthly.amount),`${d.range.from} — ${d.range.to}`]])+`<div class="a-columns"><section class="card"><h2>${tr('Təsdiq gözləyən həkimlər','Врачи на проверке','Doctors awaiting approval')}</h2>${table([tr('Həkim','Врач','Doctor'),'Email',tr('Əməliyyat','Действие','Action')],d.pending.map(u=>`<tr><td>${E(u.name)}</td><td>${E(u.email)}</td><td>${button(tr('Təsdiqlə','Подтвердить','Approve'),'financeApprove',`data-id="${E(u.id)}"`)}</td></tr>`).join(''),tr('Gözləyən qeydiyyat yoxdur.','Нет ожидающих регистраций.','No pending registrations.'))}</section><section class="card"><h2>${tr('İdarəetmə','Управление','Management')}</h2><div class="a-shortcuts"><a href="#/admin/earnings-settings"><strong>${E(l.rules)}</strong><span>${tr('Ümumi qayda və həkimə özəl faiz / AZN','Общее правило и персональные % / AZN','Default and doctor-specific % / AZN')}</span></a><a href="#/admin/earnings"><strong>${E(l.report)}</strong><span>${tr('Tarix aralığı, aylıq cəm və CSV','Период, итоги месяца и CSV','Date range, monthly totals and CSV')}</span></a><a href="#/admin/payments"><strong>${E(l.payments)}</strong><span>${tr('Bank məlumatları və provayder','Банковские данные и провайдер','Bank details and payment provider')}</span></a></div></section></div><p class="a-explanation">${E(basis())}</p>${d.monthly.unallocated?R.note(tr(`${d.monthly.unallocated} rapor üçün qazanc qaydası təyin edilməyib. Qazanc ayarlarında hesablayın.`,`${d.monthly.unallocated} заключений без правила заработка. Задайте его в настройках.`,`${d.monthly.unallocated} reports have no earning rule. Configure it in settings.`)):''}`);
 }
 function ruleForm(uid,r,defaultRule){return `<form data-form="financeRule" class="a-rule-form"><input type="hidden" name="doctor_id" value="${E(uid)}"><label class="field">${tr('Hesablama üsulu','Способ расчёта','Calculation method')}<select name="mode"><option value="percentage" ${r?.mode==='percentage'?'selected':''}>${tr('Faiz (%)','Процент (%)','Percentage (%)')}</option><option value="fixed" ${r?.mode==='fixed'?'selected':''}>${tr('Sabit məbləğ (AZN)','Фиксированная сумма (AZN)','Fixed amount (AZN)')}</option></select></label><label class="field">${tr('Faiz / məbləğ','Процент / сумма','Percentage / amount')}<input name="value" type="number" min="0" max="10000" step="0.01" value="${r?E(r.value):''}" placeholder="${E(defaultRule?ruleText(defaultRule):'0.00')}" required></label><button class="btn btn-primary" type="submit">${R.t('Saxla')}</button></form>`;}
 function settings(){const l=labels(),item=resource('/admin/earning-rules');if(!item.data)return shell(l.rules,heading(l.rules)+pending(item));const d=item.data;
  return shell(l.rules,heading(l.rules,tr('Həkimə ödəniləcək payı təyin edin','Задайте долю врача','Set the doctor’s share'))+`<p class="a-explanation">${tr('Faiz pasiyentin faktiki ödədiyi məbləğdən hesablanır. Sabit məbləğ hər tamamlanmış rapora görə AZN ilə hesablanır. Dəyişikliklər əvvəl hesablanmış qazanclara təsir etmir.','Процент рассчитывается от фактической оплаты пациента. Фиксированная сумма в AZN начисляется за завершённое заключение. Изменения не затрагивают ранее рассчитанный заработок.','Percentage is based on the patient’s actual payment. Fixed AZN is earned per completed report. Changes preserve previously calculated earnings.')}</p><section class="card a-default-rule"><div><h2>${tr('Ümumi qazanc qaydası','Общее правило','Default earning rule')}</h2><p>${tr('Fərdi qayda təyin edilməyən həkimlərə tətbiq olunur.','Применяется к врачам без личного правила.','Applies to doctors without an override.')}</p><span class="badge muted">${E(ruleText(d.default))}</span></div>${ruleForm('*',d.default)}</section><section class="card"><h2>${tr('Həkimə özəl qaydalar','Персональные правила','Doctor-specific rules')}</h2>${d.doctors.length?d.doctors.map(u=>{const r=d.overrides.find(x=>x.doctor_id===u.id);return `<article class="a-doctor-rule"><div class="a-doctor-name"><strong>${E(u.name)}</strong><small>${E(u.email)} · ${u.approved?tr('Təsdiqlənib','Подтверждён','Approved'):tr('Təsdiq gözləyir','На проверке','Pending approval')}</small><span>${r?tr('Fərdi qayda','Личное правило','Custom rule'):tr('Ümumi qayda','Общее правило','Default rule')}: ${E(ruleText(r||d.default))}</span></div>${ruleForm(u.id,r,d.default)}<div class="button-row">${r?button(tr('Ümumi qaydaya qaytar','Использовать общее правило','Use default rule'),'financeInherit',`data-id="${E(u.id)}"`):''}${button(tr('Hesabatı aç','Открыть отчёт','View report'),'financeDoctor',`data-id="${E(u.id)}"`)}${button(tr('Hesablanmamış qazancları hesabla','Рассчитать неначисленные суммы','Allocate uncalculated earnings'),'financeAllocate',`data-id="${E(u.id)}"`)}</div></article>`;}).join(''):`<p class="a-empty">${tr('Həkim qeydiyyatdan keçdikdə burada görünəcək.','Зарегистрированные врачи появятся здесь.','Doctors appear here after registration.')}</p>`}</section>`);
 }
 function rangeInit(){if(A.from)return;const d=new Date(Date.now()+14400000).toISOString().slice(0,10);A.from=d.slice(0,7)+'-01';A.to=d;}
 function report(){rangeInit();const own=!owner(),l=labels(),title=own?l.mine:l.report,query=new URLSearchParams({from:A.from,to:A.to,...(!own&&A.doctor?{doctor:A.doctor}:{})}),item=resource((own?'/me/earnings':'/admin/earnings')+'?'+query);const d=item.data;
  const filter=`<section class="card a-filter"><form data-form="financeRange"><label class="field">${tr('Başlanğıc','С','From')}<input type="date" name="from" value="${E(A.from)}" required></label><label class="field">${tr('Son tarix','По','Through')}<input type="date" name="to" value="${E(A.to)}" required></label>${!own?`<label class="field">${tr('Həkim','Врач','Doctor')}<select name="doctor"><option value="">${tr('Bütün həkimlər','Все врачи','All doctors')}</option>${(d?.doctors||[]).map(u=>`<option value="${E(u.id)}" ${A.doctor===u.id?'selected':''}>${E(u.name)}</option>`).join('')}</select></label>`:''}<button type="submit" class="btn btn-primary">${tr('Hesabatı göstər','Показать отчёт','Show report')}</button></form><div class="button-row">${button(tr('Bu ay','Этот месяц','This month'),'financeMonth','data-offset="0"')}${button(tr('Keçən ay','Прошлый месяц','Last month'),'financeMonth','data-offset="-1"')}${d?button(tr('CSV yüklə','Скачать CSV','Download CSV'),'financeCsv'):''}</div></section>`;
  if(!d)return shell(title,heading(title)+filter+pending(item));A.lastReport=d;
  const heads=[tr('Həkim','Врач','Doctor'),tr('Rapor sayı','Заключений','Reports'),tr('Ödənilən məbləğ','Оплачено','Paid amount'),tr('Həkim qazancı','Заработок врача','Doctor earnings'),tr('Saytın payı','Доля сайта','Site share')];
  return shell(title,heading(title)+filter+cards([[heads[1],d.total.count],[heads[2],money(d.total.gross)],[heads[3],money(d.total.amount)],[heads[4],money(d.total.platform)]])+`<p class="a-explanation">${E(basis())} ${tr('Hər iki seçilmiş gün hesabata daxildir. Məbləğlər həkimə hesablanmış qazancdır; bank köçürməsi bu paneldən aparılmır.','Обе выбранные даты включены. Это начисленный заработок; банковские переводы здесь не выполняются.','Both selected dates are included. Amounts are earned balances; this panel does not transfer funds.')}</p>${d.total.unallocated?`<p class="a-warning" role="status">${tr(`${d.total.unallocated} rapor hesablanmayıb: qazanc qaydası yoxdur. Bu məbləğlər həkim və sayt payına daxil deyil.`,`${d.total.unallocated} заключений без правила. Их суммы не включены в доли врача и сайта.`,`${d.total.unallocated} reports have no rule. Their amounts are excluded from doctor and site shares.`)}</p>`:''}${own?`<p>${tr('Cari qaydanız','Ваше текущее правило','Your current rule')}: <strong>${E(ruleText(d.rule))}</strong></p>`:`<section class="card"><h2>${tr('Həkim üzrə yekun','Итоги по врачам','Totals by doctor')}</h2>${table(heads,d.groups.map(g=>`<tr><td>${E(g.name)}</td><td>${g.count}</td><td>${money(g.gross)}</td><td><strong>${money(g.amount)}</strong></td><td>${money(g.platform)}</td></tr>`).join(''))}</section>`}<section class="card"><h2>${tr('Raporlar üzrə hesablanma','Начисления по заключениям','Earnings by report')}</h2>${table([tr('Təsdiq tarixi','Дата подтверждения','Approved at'),tr('Müraciət','Заявка','Case'),heads[0],heads[2],tr('Qayda','Правило','Rule'),heads[3]],d.entries.map(e=>`<tr><td>${E(date(e.earned_at))}</td><td class="a-case-id">${E(e.case_id)}</td><td>${E(e.doctor_name)}</td><td>${money(e.gross)}</td><td>${E(ruleText({mode:e.mode,value:e.value/100}))}</td><td><strong>${e.amount===null?'—':money(e.amount)}</strong></td></tr>`).join(''),tr('Bu tarix aralığında real ödənişli tamamlanmış rapor yoxdur.','За этот период нет завершённых заключений с реальной оплатой.','No completed, genuinely paid reports in this date range.'))}</section>`);
 }
 R.actions.financeRefresh=()=>{A.cache.clear();R.render();};
 R.forms.financeRule=async d=>{await R.request('/admin/earning-rules',{method:'PUT',body:d});A.cache.clear();R.render();R.toast(tr('Qazanc qaydası saxlanıldı.','Правило сохранено.','Earning rule saved.'));};
 R.actions.financeInherit=async el=>{await R.request('/admin/earning-rules',{method:'DELETE',body:{doctor_id:el.dataset.id}});A.cache.clear();R.render();};
 R.actions.financeApprove=async el=>{await R.request('/admin/approve',{method:'POST',body:{id:el.dataset.id,kind:'doctor'}});A.cache.clear();R.render();R.toast(tr('Həkim təsdiqləndi.','Врач подтверждён.','Doctor approved.'));};
 R.actions.financeAllocate=async el=>{R.modal(tr('Hesablanmamış qazanclar','Неначисленные суммы','Uncalculated earnings'),`<p>${tr('Bu həkimin qaydasız qalmış bütün raporları hazırkı qayda ilə hesablanacaq. Artıq hesablanmış məbləğlər dəyişməyəcək.','Все заключения этого врача без начисления будут рассчитаны по текущему правилу. Ранее начисленные суммы сохранятся.','All this doctor’s unallocated reports will use the current rule. Previously calculated amounts will remain unchanged.')}</p>${button(tr('Hesabla','Рассчитать','Calculate'),'financeAllocateConfirm',`data-id="${E(el.dataset.id)}"`)}`);};
 R.actions.financeAllocateConfirm=async el=>{const r=await R.request('/admin/earnings/allocate',{method:'POST',body:{doctor_id:el.dataset.id}});R.closeModal();A.cache.clear();R.render();R.toast(tr(`${r.count} rapor hesablandı.`,`${r.count} заключений рассчитано.`,`${r.count} reports calculated.`));};
 R.actions.financeDoctor=el=>{A.doctor=el.dataset.id;R.go('/admin/earnings');};
 R.forms.financeRange=d=>{if(d.from>d.to)throw Error(tr('Başlanğıc tarix son tarixdən böyük ola bilməz.','Начальная дата не может быть позже конечной.','Start date must not follow end date.'));A.from=d.from;A.to=d.to;A.doctor=d.doctor||'';A.cache.clear();R.render();};
 R.actions.financeMonth=el=>{const today=new Date(Date.now()+14400000),year=today.getUTCFullYear(),month=today.getUTCMonth()+Number(el.dataset.offset);A.from=new Date(Date.UTC(year,month,1)).toISOString().slice(0,10);A.to=new Date(Date.UTC(year,month+1,0)).toISOString().slice(0,10);A.cache.clear();R.render();};
 R.actions.financeCsv=()=>{const d=A.lastReport;if(!d)return;const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const lines=[['Tarix (Bakı)','Müraciət','Həkim','Ödəniş AZN','Qayda','Həkim qazancı AZN'],...d.entries.map(e=>[date(e.earned_at),e.case_id,e.doctor_name,(e.gross/100).toFixed(2),ruleText({mode:e.mode,value:e.value/100}),e.amount===null?'':(e.amount/100).toFixed(2)])];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=`RADAZ-${d.range.from}-${d.range.to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 let doctorCabinet=false;
 R.actions.openDoctorCabinet=()=>{doctorCabinet=true;R.go('/dashboard');R.render();};
 const oldAdmin=P.adminPage;P.adminPage=()=>{if(!owner())return R.authPage(false);const route=R.state.route;if(route==='/admin/overview')return overview();if(route==='/admin/earnings-settings')return settings();if(route==='/admin/earnings')return report();const el=document.createElement('div');el.innerHTML=oldAdmin();el.querySelectorAll('.demo-workspace-banner,.p-admin-tabs').forEach(n=>n.remove());return shell(labels()[route.split('/').at(-1)]||labels().overview,el.querySelector('.dashboard-content')?.innerHTML||el.innerHTML);};
 R.actions.ownerLogin=async()=>{const r=await R.request('/auth/owner',{method:'POST',body:{}});R.state.user={...r.user,role:'doctor',is_owner:true};A.cache.clear();P.settings=null;P.viewer=null;P.contact=null;doctorCabinet=false;R.go('/admin/overview');};
 const render=R.render;R.render=()=>{const route=R.state.route;if(route==='/earnings'){R.$('#app').innerHTML=R.state.user&&['doctor','admin'].includes(R.state.user.role)?report():R.authPage(false);document.title=labels().mine+' · RADAZ';}else if(route==='/dashboard'&&owner()&&!doctorCabinet){R.$('#app').innerHTML=overview();document.title=labels().overview+' · RADAZ';}else render();if(route.startsWith('/admin/'))document.title=(labels()[route.split('/').at(-1)]||labels().overview)+' · RADAZ';if(!route.startsWith('/admin/')&&route!=='/earnings'){R.$$('.dashboard-sidebar nav').forEach(nav=>{const href=owner()?'#/admin/overview':'#/earnings';if(!nav.querySelector(`[href="${href}"]`)&&R.state.user?.role==='doctor')nav.insertAdjacentHTML('afterbegin',`<a href="${href}">${R.icon('file',18)} ${E(owner()?labels().overview:labels().mine)}</a>`);});}if(owner())R.$$('.site-header a[href="#/dashboard"],.header a[href="#/dashboard"]').forEach(a=>{a.href='#/admin/overview';a.textContent=labels().overview;});};
 for(const key of ['login','logout','register']){const fn=R.api[key];R.api[key]=async(...args)=>{A.cache.clear();A.lastReport=null;A.doctor='';doctorCabinet=false;return fn(...args);};}
 if(R.$('#app').children.length)R.render();
})();
